<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>2048</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    background: #1a1a2e;
    color: #eee;
    font-family: Arial, sans-serif;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    flex-direction: column;
  }
  h1 { font-size: 2.5rem; margin-bottom: 0.25rem; color: #f0e68c; }
  #score-display {
    font-size: 1.3rem;
    margin-bottom: 0.75rem;
    background: #16213e;
    padding: 0.4rem 1.2rem;
    border-radius: 8px;
  }
  #score { font-weight: bold; color: #f0e68c; }
  #board-container {
    background: #16213e;
    padding: 10px;
    border-radius: 12px;
    box-shadow: 0 4px 20px rgba(0,0,0,0.5);
  }
  #board {
    display: grid;
    grid-template-columns: repeat(4, 80px);
    grid-template-rows: repeat(4, 80px);
    gap: 8px;
    background: #0f3460;
    border-radius: 8px;
    padding: 8px;
  }
  .tile {
    width: 80px;
    height: 80px;
    display: flex;
    justify-content: center;
    align-items: center;
    font-size: 1.6rem;
    font-weight: bold;
    border-radius: 6px;
    color: #eee;
    background: #1a1a40;
    transition: all 0.1s ease;
  }
  .tile[data-value="2"]   { background: #4a5568; }
  .tile[data-value="4"]   { background: #5a6578; }
  .tile[data-value="8"]   { background: #e8a838; color: #1a1a2e; }
  .tile[data-value="16"]  { background: #e09828; color: #1a1a2e; }
  .tile[data-value="32"]  { background: #d88020; color: #eee; }
  .tile[data-value="64"]  { background: #d06810; color: #eee; }
  .tile[data-value="128"] { background: #c85008; font-size: 1.4rem; }
  .tile[data-value="256"] { background: #b83800; font-size: 1.4rem; }
  .tile[data-value="512"] { background: #a83000; font-size: 1.4rem; }
  .tile[data-value="1024"]{ background: #982000; font-size: 1.2rem; }
  .tile[data-value="2048"]{ background: #c5d63a; color: #1a1a2e; font-size: 1.2rem; }
  #reset {
    margin-top: 1rem;
    padding: 0.6rem 2rem;
    font-size: 1.1rem;
    background: #533483;
    color: #eee;
    border: none;
    border-radius: 8px;
    cursor: pointer;
  }
  #reset:hover { background: #6a42a0; }
</style>
</head>
<body>

<h1>2048</h1>
<div id="score-display">Score: <span id="score">0</span></div>
<div id="board-container">
  <div id="board"></div>
</div>
<button id="reset">New Game</button>

<script>
(function() {
  const SIZE = 4;
  let board_ = [];
  let score_ = 0;

  function createBoard() {
    return Array.from({ length: SIZE }, () => Array(SIZE).fill(0));
  }

  function randomEmptyCells() {
    const cells = [];
    for (let r = 0; r < SIZE; r++)
      for (let c = 0; c < SIZE; c++)
        if (board_[r][c] === 0) cells.push([r, c]);
    return cells;
  }

  function addRandomTile() {
    const empty = randomEmptyCells();
    if (empty.length === 0) return false;
    const [r, c] = empty[Math.floor(Math.random() * empty.length)];
    board_[r][c] = Math.random() < 0.9 ? 2 : 4;
    return true;
  }

  function cloneBoard(b) {
    return b.map(row => Array.from(row));
  }

  function boardsEqual(a, b) {
    for (let r = 0; r < SIZE; r++)
      for (let c = 0; c < SIZE; c++)
        if (a[r][c] !== b[r][c]) return false;
    return true;
  }

  function moveLeft(b) {
    const merged = b.map(row => Array(SIZE).fill(false));
    let scoreGained = 0;
    for (let r = 0; r < SIZE; r++) {
      let col = 0;
      for (let c = 0; c < SIZE; c++) {
        if (b[r][c] === 0) continue;
        const val = b[r][c];
        if (col > 0 && !merged[r][col - 1] && b[r][col - 1] === val) {
          b[r][col - 1] *= 2;
          scoreGained += b[r][col - 1];
          merged[r][col - 1] = true;
        } else {
          if (col !== c) b[r][col] = val;
          col++;
        }
      }
      for (let c = col; c < SIZE; c++) b[r][c] = 0;
    }
    return scoreGained;
  }

  function moveRight(b) {
    const merged = b.map(row => Array(SIZE).fill(false));
    let scoreGained = 0;
    for (let r = 0; r < SIZE; r++) {
      let col = SIZE - 1;
      for (let c = SIZE - 1; c >= 0; c--) {
        if (b[r][c] === 0) continue;
        const val = b[r][c];
        if (col < SIZE - 1 && !merged[r][col + 1] && b[r][col + 1] === val) {
          b[r][col + 1] *= 2;
          scoreGained += b[r][col + 1];
          merged[r][col + 1] = true;
        } else {
          if (col !== c) b[r][col] = val;
          col--;
        }
      }
      for (let c = 0; c <= col; c++) b[r][c] = 0;
    }
    return scoreGained;
  }

  function moveUp(b) {
    const merged = Array.from({ length: SIZE }, () => Array(SIZE).fill(false));
    let scoreGained = 0;
    for (let c = 0; c < SIZE; c++) {
      let row = 0;
      for (let r = 0; r < SIZE; r++) {
        if (b[r][c] === 0) continue;
        const val = b[r][c];
        if (row > 0 && !merged[row - 1][c] && b[row - 1][c] === val) {
          b[row - 1][c] *= 2;
          scoreGained += b[row - 1][c];
          merged[row - 1][c] = true;
        } else {
          if (row !== r) b[row][c] = val;
          row++;
        }
      }
      for (let r = row; r < SIZE; r++) b[r][c] = 0;
    }
    return scoreGained;
  }

  function moveDown(b) {
    const merged = Array.from({ length: SIZE }, () => Array(SIZE).fill(false));
    let scoreGained = 0;
    for (let c = 0; c < SIZE; c++) {
      let row = SIZE - 1;
      for (let r = SIZE - 1; r >= 0; r--) {
        if (b[r][c] === 0) continue;
        const val = b[r][c];
        if (row < SIZE - 1 && !merged[row + 1][c] && b[row + 1][c] === val) {
          b[row + 1][c] *= 2;
          scoreGained += b[row + 1][c];
          merged[row + 1][c] = true;
        } else {
          if (row !== r) b[row][c] = val;
          row--;
        }
      }
      for (let r = 0; r <= row; r++) b[r][c] = 0;
    }
    return scoreGained;
  }

  function render() {
    const boardEl = document.getElementById('board');
    boardEl.innerHTML = '';
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        const tile = document.createElement('div');
        tile.className = 'tile';
        const val = board_[r][c];
        if (val > 0) {
          tile.textContent = val;
          tile.setAttribute('data-value', val);
        } else {
          tile.textContent = '';
          tile.setAttribute('data-value', '0');
        }
        boardEl.appendChild(tile);
      }
    }
    document.getElementById('score').textContent = score_;
  }

  function gameReset() {
    board_ = createBoard();
    score_ = 0;
    addRandomTile();
    addRandomTile();
    render();
  }

  window.game = {
    get size() { return SIZE; },

    reset: function() {
      gameReset();
    },

    move: function(direction) {
      const oldBoard = cloneBoard(board_);
      let scoreGained = 0;
      switch (direction) {
        case 'left':  scoreGained = moveLeft(cloneBoardForMerge(board_)); break;
        case 'right': scoreGained = moveRight(cloneBoardForMerge(board_)); break;
        case 'up':    scoreGained = moveUp(cloneBoardForMerge(board_)); break;
        case 'down':  scoreGained = moveDown(cloneBoardForMerge(board_)); break;
      }

      if (boardsEqual(board_, oldBoard)) {
        return false;
      }

      score_ += scoreGained;

      addRandomTile();
      render();
      return true;
    },

    board: function() {
      return cloneBoard(board_);
    },

    setBoard: function(arr) {
      board_ = arr.map(row => Array.from(row));
      score_ = 0;
      render();
    },

    score: function() {
      return score_;
    }
  };

  // Helper to get a modifiable copy for move functions
  function cloneBoardForMerge(b) {
    return b.map(row => Array.from(row));
  }

  // Initialize
  gameReset();

  // Keyboard controls
  document.addEventListener('keydown', function(e) {
    const keyMap = {
      ArrowLeft: 'left',
      ArrowRight: 'right',
      ArrowUp: 'up',
      ArrowDown: 'down'
    };
    if (keyMap[e.key]) {
      e.preventDefault();
      window.game.move(keyMap[e.key]);
    }
  });

  // Reset button
  document.getElementById('reset').addEventListener('click', function() {
    window.game.reset();
  });
})();
</script>

</body>
</html>
